-----------------------------------------------------------------------------------
--!     @file    conv_mnist_2_layers
--!     @brief        This testbench verifies the functionality of the conv layer
--!     @details      It initializes the inputs, applies test vectors, and checks the outputs.
--!     @author       Timothée Charrier
-----------------------------------------------------------------------------------

library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD.all;
use ieee.std_logic_textio.all;
use std.textio.all;

library LIB_RTL;
use LIB_RTL.types_pkg.all;

entity conv_mnist_2_layers is
end entity;

architecture conv_mnist_2_layers_arch of conv_mnist_2_layers is
    -------------------------------------------------------------------------------------
    -- CONSTANTS for first layer
    -------------------------------------------------------------------------------------
    constant i_clk_period     : time      := 10 ns;
    constant USE_MAC_ARCH     : std_logic := '1';
    constant DO_PIPELINE      : std_logic := '1';
    constant BITWIDTH         : integer   := 16;
    constant INPUT_SIZE_1     : integer   := 28;
    constant CHANNEL_NUMBER_1 : integer   := 1;
    constant KERNEL_SIZE_1    : integer   := 3;
    constant KERNEL_NUMBER_1  : integer   := 32;
    constant PADDING_1        : integer   := 1;
    constant STRIDE_1         : integer   := 2;
    constant EPSILON_1        : integer   := 0;

    -------------------------------------------------------------------------------------
    -- SIGNALS for first layer
    -------------------------------------------------------------------------------------
    signal i_data_valid_1       : std_logic := '0';
    signal i_data_1             : t_volume(CHANNEL_NUMBER_1 - 1 downto 0)(INPUT_SIZE_1 - 1 downto 0)(INPUT_SIZE_1 - 1 downto 0)(BITWIDTH - 1 downto 0);
    signal i_kernel_1           : t_input_feature(KERNEL_NUMBER_1 - 1 downto 0)(CHANNEL_NUMBER_1 - 1 downto 0)(KERNEL_SIZE_1 - 1 downto 0)(KERNEL_SIZE_1 - 1 downto 0)(BITWIDTH - 1 downto 0);
    signal i_bias_conv2d_1      : t_vec(KERNEL_NUMBER_1 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal i_running_mean_1     : t_vec(KERNEL_NUMBER_1 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal i_weight_1           : t_vec(KERNEL_NUMBER_1 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal i_bias_batchnorm2d_1 : t_vec(KERNEL_NUMBER_1 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal o_data_1             : t_volume(KERNEL_NUMBER_1 - 1 downto 0)((INPUT_SIZE_1 + 2 * PADDING_1 - KERNEL_SIZE_1)/STRIDE_1 + 1 - 1 downto 0)((INPUT_SIZE_1 + 2 * PADDING_1 - KERNEL_SIZE_1)/STRIDE_1 + 1 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal o_data_valid_1       : std_logic;

    -------------------------------------------------------------------------------------
    -- CONSTANTS for second layer
    -------------------------------------------------------------------------------------
    constant INPUT_SIZE_2     : integer := (INPUT_SIZE_1 + 2 * PADDING_1 - KERNEL_SIZE_1)/STRIDE_1 + 1;
    constant CHANNEL_NUMBER_2 : integer := KERNEL_NUMBER_1;
    constant KERNEL_SIZE_2    : integer := 3;
    constant KERNEL_NUMBER_2  : integer := 64;
    constant PADDING_2        : integer := 0;
    constant STRIDE_2         : integer := 1;
    constant EPSILON_2        : integer := 0;

    -------------------------------------------------------------------------------------
    -- SIGNALS for first layer
    -------------------------------------------------------------------------------------
    signal i_data_2             : t_volume(CHANNEL_NUMBER_2 - 1 downto 0)(INPUT_SIZE_2 - 1 downto 0)(INPUT_SIZE_2 - 1 downto 0)(BITWIDTH - 1 downto 0);
    signal i_kernel_2           : t_input_feature(KERNEL_NUMBER_2 - 1 downto 0)(CHANNEL_NUMBER_2 - 1 downto 0)(KERNEL_SIZE_2 - 1 downto 0)(KERNEL_SIZE_2 - 1 downto 0)(BITWIDTH - 1 downto 0);
    signal i_bias_conv2d_2      : t_vec(KERNEL_NUMBER_2 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal i_running_mean_2     : t_vec(KERNEL_NUMBER_2 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal i_weight_2           : t_vec(KERNEL_NUMBER_2 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal i_bias_batchnorm2d_2 : t_vec(KERNEL_NUMBER_2 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal o_data_2             : t_volume(KERNEL_NUMBER_2 - 1 downto 0)((INPUT_SIZE_2 + 2 * PADDING_2 - KERNEL_SIZE_2)/STRIDE_2 + 1 - 1 downto 0)((INPUT_SIZE_2 + 2 * PADDING_2 - KERNEL_SIZE_2)/STRIDE_2 + 1 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
    signal o_data_valid_2       : std_logic;

    -------------------------------------------------------------------------------------
    -- Shared Signals
    -------------------------------------------------------------------------------------
    signal clock        : std_logic := '0';
    signal reset_n      : std_logic := '0';
    signal i_sys_enable : std_logic := '0';

    -- File variables
    file output_file_first_layer  : text;
    file output_file_second_layer : text;

    -------------------------------------------------------------------------------------
    -- COMPONENTS
    -------------------------------------------------------------------------------------
    component conv
        generic (
            USE_MAC_ARCH   : std_logic;
            DO_PIPELINE    : std_logic;
            BITWIDTH       : integer;
            INPUT_SIZE     : integer;
            CHANNEL_NUMBER : integer;
            KERNEL_SIZE    : integer;
            KERNEL_NUMBER  : integer;
            PADDING        : integer;
            STRIDE         : integer;
            EPSILON        : integer
        );
        port (
            clock              : in std_logic;
            reset_n            : in std_logic;
            i_sys_enable       : in std_logic;
            i_data_valid       : in std_logic;
            i_data             : in t_volume(CHANNEL_NUMBER - 1 downto 0)(INPUT_SIZE - 1 downto 0)(INPUT_SIZE - 1 downto 0)(BITWIDTH - 1 downto 0);
            i_kernel           : in t_input_feature(KERNEL_NUMBER - 1 downto 0)(CHANNEL_NUMBER - 1 downto 0)(KERNEL_SIZE - 1 downto 0)(KERNEL_SIZE - 1 downto 0)(BITWIDTH - 1 downto 0);
            i_bias_conv2d      : in t_vec(KERNEL_NUMBER - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
            i_running_mean     : in t_vec(KERNEL_NUMBER - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
            i_weight           : in t_vec(KERNEL_NUMBER - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
            i_bias_batchnorm2d : in t_vec(KERNEL_NUMBER - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
            o_data             : out t_volume(KERNEL_NUMBER - 1 downto 0)((INPUT_SIZE + 2 * PADDING - KERNEL_SIZE)/STRIDE + 1 - 1 downto 0)((INPUT_SIZE + 2 * PADDING - KERNEL_SIZE)/STRIDE + 1 - 1 downto 0)(2 * BITWIDTH - 1 downto 0);
            o_data_valid       : out std_logic
        );
    end component;

