    -----------------------------------------------------------------------------------
    -- TEST process
    -----------------------------------------------------------------------------------
    stimulus : process
        variable line_buffer : line;
    begin
        -- Reset the system
        reset_n <= '0';
        wait for i_clk_period/2;
        reset_n <= '1';

        -- Enable the system
        i_sys_enable <= '1';

        i_data_valid_1 <= '1';
        wait for i_clk_period * 2;
        i_data_valid_1 <= '0';

        -- Wait for output to be valid and write to file
        wait until o_data_valid_1 = '1';
        report "End of computation of first layer at time " & time'image(now);

        -- Open the file
        file_open(output_file_first_layer, "conv_output_results_first_layer.txt", write_mode);

        for k in 0 to KERNEL_NUMBER_1 - 1 loop
            for i in ((INPUT_SIZE_1 + 2 * PADDING_1 - KERNEL_SIZE_1)/STRIDE_1 + 1 - 1) downto 0 loop
                for j in ((INPUT_SIZE_1 + 2 * PADDING_1 - KERNEL_SIZE_1)/STRIDE_1 + 1 - 1) downto 0 loop
                    write(line_buffer, to_integer(signed(o_data_1(k)(i)(j))));
                    writeline(output_file_first_layer, line_buffer);
                end loop;
            end loop;
        end loop;

        -- Close the file
        file_close(output_file_first_layer);

        -- Wait for output to be valid and write to file
        wait until o_data_valid_2 = '1';
        report "End of computation of second layer at time " & time'image(now);

        -- Open the file
        file_open(output_file_second_layer, "conv_output_results_second_layer.txt", write_mode);

        for k in 0 to KERNEL_NUMBER_2 - 1 loop
            for i in ((INPUT_SIZE_2 + 2 * PADDING_2 - KERNEL_SIZE_2)/STRIDE_2 + 1 - 1) downto 0 loop
                for j in ((INPUT_SIZE_2 + 2 * PADDING_2 - KERNEL_SIZE_2)/STRIDE_2 + 1 - 1) downto 0 loop
                    write(line_buffer, to_integer(signed(o_data_2(k)(i)(j))));
                    writeline(output_file_second_layer, line_buffer);
                end loop;
            end loop;
        end loop;

        -- Close the file
        file_close(output_file_second_layer);

        -- Finish the simulation
        wait;
    end process stimulus;

end architecture;

configuration conv_mnist_2_layers_conf of conv_mnist_2_layers is
    for conv_mnist_2_layers_arch
        for all : conv
            use configuration LIB_RTL.conv_conf;
        end for;
    end for;
end configuration conv_mnist_2_layers_conf;